CREATE TRIGGER cla_native_v2_head_revision AFTER UPDATE OF revision ON cla_native_v2_state BEGIN
 UPDATE cla_native_v2_head_requests SET status='pending',attempt='',lease_until=0,result='' WHERE status IN ('done','running');
END

CREATE TRIGGER cla_native_v2_publication_slot_enroll AFTER INSERT ON cla_native_v2_publication_attempts
 WHEN EXISTS(SELECT 1 FROM cla_native_v2__guards WHERE id='confirmation-slot:'||NEW.id AND ok=1) BEGIN
 INSERT INTO cla_native_v2_slot_policy SELECT 1,'cla-confirmation-slot-v1',NEW.id,NEW.id,CAST(strftime('%s','now') AS INTEGER)
 WHERE NOT EXISTS(SELECT 1 FROM cla_native_v2_slot_policy);
 UPDATE cla_native_v2_slot_policy SET active_attempt=NEW.id WHERE id=1 AND active_attempt IS NULL;
 SELECT CASE WHEN (SELECT active_attempt FROM cla_native_v2_slot_policy WHERE id=1) IS NOT NEW.id THEN RAISE(ABORT,'slot_enrollment_failed') END;
 DELETE FROM cla_native_v2__guards WHERE id='confirmation-slot:'||NEW.id;
END
